"""Generate the Raze rules shared by the native controller and browser lab."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
def write_rules(path,text):
 # Identical generated Rust must not invalidate both native and WASM builds.
 if not path.exists() or path.read_text(encoding='utf-8')!=text:path.write_text(text,encoding='utf-8')
d=json.loads((ROOT/'rules/raze.json').read_text(encoding='utf-8'))
lines=['// Generated by tools/generate-raze.py. Edit rules/raze.json.',
       f'pub const TPS: i64 = {d["ticks_per_second"]};',
       'pub const RULES_REVISION: &str = '+json.dumps(d['rules_revision'])+';']
lines += [f'pub const {k}: i64 = {v};' for k,v in d['constants'].items()]
write_rules(ROOT/'native/tfm2_custom_ai/src/raze_data.rs','\n'.join(lines)+'\n')
(ROOT/'editor/raze-data.js').write_text('/* Generated by tools/generate-raze.py */\nwindow.RAZE_RULES='+json.dumps(d,separators=(',',':'))+';\n',encoding='utf-8')
gunlines=['// Generated by tools/generate-raze.py from the shared Omen/Raze weapon table.']
for key,field in [('PRICES','price'),('RANGES','range'),('ATTACK_MODIFIERS','attack_modifier'),('SPEED_MODIFIERS','speed_modifier'),('TIERS','tier')]:
 gunlines.append(f'const {key}: [i64; 6] = '+json.dumps([g[field] for g in d['weapons']])+';')
for key,value in d['judge'].items():gunlines.append(f'pub const JUDGE_{key.upper()}: i64 = {value};')
write_rules(ROOT/'native/tfm2_custom_ai/src/valorant_gun_data.rs','\n'.join(gunlines)+'\n')
print('Raze native/editor rules generated')

# Champion action shells follow Omen's existing native-owned convention.
omen=json.loads((ROOT/'mods/tfm2_valorant/champion/tfm2_valorant_omen.data_champion').read_text(encoding='utf-8'))
champ=json.loads(json.dumps(omen));champ['id']=d['identity']['id'];champ['category']='Range';champ['tags']=d['identity']['tags'];champ['sprite']='asset/tfm2_valorant/champions/tfm2_valorant_raze';champ['passive']={'passive_ref':'tfm2_custom_ai:raze','params':{}}
for key in ['stat','growth']:champ[key].update(d['stats' if key=='stat' else 'growth'])
for slot in ['skill','skill2','ult']:champ[slot]['description']='#asset/base/text/champion?description.tfm2_valorant_raze.'+slot
champ['view_buffs']=[v for v in omen.get('view_buffs',[]) if v.get('name','').startswith(('omn_gun','omn_arm','omn_cr','omn_cash'))];champ['view_effects']=[]
for tag in ['grenade_prep','pack_throw','bot_prep','rocket_equip','rocket_ready','rocket_release','buy','grenade_warning','cluster_warning','bot_warning','rocket_path','satchel_blast','grenade_blast','cluster_blast','rocket_blast','landing','grenade_flight','rocket_flight','satchel','bot']:
 champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_'+tag,anim='asset/tfm2_valorant/vfx/raze',tag=tag,z=5,is_follow=tag in ['satchel','bot','buy']))
for direction in range(8):champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_rocket_flight_'+str(direction),anim='asset/tfm2_valorant/vfx/raze',tag='rocket_flight_'+str(direction),z=5,is_follow=False))
for v in champ['view_effects']:
 if v['name']=='tfm2_valorant_raze_rocket_blast':v['tag']='rocket_blast_large'
 for old in ['satchel_blast','grenade_blast','grenade_warning','cluster_blast','cluster_warning']:
  if v['name']=='tfm2_valorant_raze_'+old:v['tag']=old+'_wide'
champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_rocket_impact_warning',anim='asset/tfm2_valorant/vfx/raze',tag='rocket_impact_warning',z=5,is_follow=False))
for tag in ['satchel_ground','satchel_north','satchel_east','satchel_south','satchel_west']+[f'rocket_impact_warning_{n}' for n in range(8)]:
 champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_'+tag,anim='asset/tfm2_valorant/vfx/raze',tag=tag,z=5,is_follow=tag.startswith('satchel_')))
# Reuse Omen's gun and credit indicators exactly; the asset belongs to the same pack.
for view in omen.get('view_effects',[]):
 if any(t in view.get('name','') for t in ['gun','money','credit','tracer','pellets','op_flash']):
  v=json.loads(json.dumps(view));v['name']=v['name'].replace('tfm2_valorant_omen','tfm2_valorant_raze');champ['view_effects'].append(v)
# Same purchase feedback as Omen, using the existing pixels and timing.
buy=next(v for v in omen['view_effects'] if v['name']=='tfm2_valorant_omen_buy')
buy=json.loads(json.dumps(buy));buy['name']='tfm2_valorant_raze_buy'
champ['view_effects']=[buy if v['name']==buy['name'] else v for v in champ['view_effects']]
for variant in ['','_rocket','_grenade','_pack']:
 for facing in ['r','l']:champ['view_effects'].append(dict(type='Animation',name='tfm2_valorant_raze_airborne'+variant+'_'+facing,anim=champ['sprite'],tag='airborne'+variant+'_'+facing,z=6,is_follow=False))
text={
 'name':'Raze',
 'skill':'Paint Shells: purchased cluster grenade (300 credits), 8-second reuse limit, 80000 throw range. Main blast 65 + 55% AP, then four smaller blasts (15 + 12.5% AP), at most two secondary hits per enemy. Boom Bot is an additional native ability: 300 credits, 18-second cooldown, one destructible bot, 45 + 45% AP blast. Grenade/rocket self-damage is 25% before mitigation. Omen weapon progression, prices, gun-first buying and credit income; unused utility and weapons persist through death. No mastery. All 13 pinned athlete attributes influence decisions and execution only.',
 'skill2':'Blast Pack: buy up to two charges for 200 credits each; no automatic refill. Detonate to add a radial launch impulse; air-strafe with limited sideways acceleration and retained momentum. A second satchel adds another impulse. Armed after 1 second: 20 + 15% AP and enemy knockback within 18000. Satchels have 40 HP and expire after 5 seconds without exploding. Raze stays targetable. Terrain, roots and movement-blocks constrain travel.',
 'ult':'Showstopper: ultimate unlock required; equip for 0.7 seconds and fire within 6 seconds. Cooldown 60 seconds from accepted equip. Ground endpoint or first unit/wall impact. Maximum 240 + 150% AP; continuous falloff to 25% at 40000 radius. Travel up to 240000 at 600000 units/second. Firing gives a short grounded recoil slide or an airborne third boost opposite the shot. Actual airborne flight grants 15% damage reduction; ground recoil does not. Grenade/rocket self-damage remains 25% before normal mitigation. No homing, free charges or animation-cancel skips.'}
text['skill2']+=' Actual airborne flight grants 15% incoming damage reduction, ending on landing, interruption or death; no crowd-control immunity. Judge now deals 3x basic damage through 10000, falling to 0.7x at 20000; Raze buys it for viable close entries and keeps rifles for open fights.'
C=d['constants']
text['skill']=text['skill'].replace('80000 throw range',str(C['GRENADE_RANGE'])+' throw range')+f" Main radius {C['GRENADE_RADIUS']}; four cluster centres scatter diagonally by {C['CLUSTER_OFFSET']} per axis, each with {C['CLUSTER_RADIUS']} radius."
text['skill2']=text['skill2'].replace('within 18000',f"within {C['PACK_RADIUS']}")+f" Packs stick to ground, wall faces and solid constructions. Launch impulse {C['LAUNCH_SPEED']}; air acceleration {C['AIR_ACCEL']}, preserving momentum and speed caps."
text['ult']=text['ult'].replace('240 + 150% AP',f"{C['ROCKET_DAMAGE']} + {C['ROCKET_AP']}% AP").replace('40000 radius',f"{C['ROCKET_RADIUS']} radius").replace('at 600000 units/second',f"starting at {C['ROCKET_START_SPEED']} and accelerating to {C['ROCKET_SPEED']} units/second over 0.3 seconds")+' Warns the predicted impact area; enemies attempt to escape. Surviving enemy champions, minions and summons are pushed outward over 0.2 seconds, with terrain and immunity respected.'
(ROOT/'mods/tfm2_valorant/champion/tfm2_valorant_raze.data_champion').write_text(json.dumps(champ,indent=2)+'\n',encoding='utf-8')
path=ROOT/'mods/tfm2_valorant/text/champion.i18n';loc=json.loads(path.read_text(encoding='utf-8'));loc['en']['description']['tfm2_valorant_raze']=text
for slot,value in loc['en']['description']['tfm2_valorant_omen'].items():loc['en']['description']['tfm2_valorant_omen'][slot]=value.replace('2.2x point blank','3x point blank')
path.write_text(json.dumps(loc,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'editor/raze-preset.js').write_text('window.RAZE_PRESET='+json.dumps(champ,separators=(',',':'))+';\nwindow.RAZE_TEXT='+json.dumps(text,separators=(',',':'))+';\n',encoding='utf-8')
path=ROOT/'rules/champions.json';roster=json.loads(path.read_text(encoding='utf-8'));roster['champions']=[c for c in roster['champions'] if c['id']!='tfm2_valorant_raze']
roster['champions'].append(dict(id='tfm2_valorant_raze',name='Raze',family='valorant',role='Range',native=True,basicAttack=dict(name='Purchased gun',kind='ranged',range=30000),skills=[
 dict(slot='skill',name='Paint Shells / Boom Bot',kinds=['Projectile','Aoe','Summon'],intents=['Clear','Poke','Objective','Vision'],summary='Purchased cluster grenade or destructible scouting bot; native resource and visibility gates.'),
 dict(slot='skill2',name='Blast Pack',kinds=['Dash','Aoe','Cc'],intents=['Engage','Escape','Protect'],summary='Two purchased satchels provide momentum launches and limited air strafing; armed packs displace enemies.'),
 dict(slot='ult',name='Showstopper',kinds=['Projectile','Aoe'],intents=['Engage','Poke','Objective'],summary='Equip one warned rocket; fixed flight, area falloff and reduced self-damage. Can combine with satchel entries.')]))
path.write_text(json.dumps(roster,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
